/* 04: salary retention is a monthly flow, separate from assets and other income. */
let salaryMonth=M.month(),flowView='summary';
state().v4??={density:'comfortable',wallpaper:null};
const v4=()=>state().v4??(state().v4={density:'comfortable',wallpaper:null});
const salaryLike=t=>t.salary===false?false:t.salary===true||t.kind==='salary'||/^salary-/.test(t.id||'')||/工资|薪资|薪酬|年终奖|绩效奖金/.test(t.name||'');
function salarySummary(month=M.month()){
 const current=month===M.month(),past=month<M.month(),end=M.dueDate(month,31),cutoff=past?end:current?M.today():month+'-01',days=Number(end.slice(8)),elapsed=past?days:current?Number(M.today().slice(8)):0,left=past?0:days-elapsed;
 const tx=M.monthlyTx(month),wages=v3().cash.incomes.filter(t=>t.date.startsWith(month)&&salaryLike(t)),incomeTx=tx.filter(t=>t.type==='income'&&salaryLike(t)),received=total(wages.filter(t=>t.received&&t.date<=cutoff))+total(incomeTx.filter(t=>t.date<=cutoff)),expected=past?0:total(wages.filter(t=>!t.received&&t.date>=cutoff));
 const counted=tx.filter(t=>t.date<=cutoff&&t.funding!=='assets'&&!isCredit(t)&&['expense','refund'].includes(t.type)),spent=total(counted,t=>expenseSign(t)*t.amount),allPeriods=state().debts.flatMap(d=>d.schedule.map(p=>({...p,name:d.name,debtId:d.id}))),paidRows=allPeriods.filter(p=>p.paid&&p.funding!=='assets'&&(p.paidDate||p.date).startsWith(month)),paid=total(paidRows,p=>p.total),unpaid=past?0:total(allPeriods.filter(p=>!p.paid&&p.funding!=='assets'&&p.date.startsWith(month)),p=>p.total);
 const fixed=v3().cash.fixed.filter(f=>!tx.some(t=>t.type==='expense'&&t.name.includes(f.name))),futureFixed=past?0:total(fixed),variable=counted.filter(t=>!/房租|房贷|水电|保险|年费/.test(t.name)&&!v3().cash.fixed.some(f=>t.name.includes(f.name))),daily=Math.max(0,total(variable,t=>expenseSign(t)*t.amount))/Math.max(1,elapsed),futureDaily=past?0:M.round(daily*left),now=M.round(received-spent-paid),forecast=M.round(now+expected-unpaid-futureFixed-futureDaily),salaryTotal=received+expected,retention=salaryTotal>0?forecast/salaryTotal*100:0;
 const otherIncome=total(v3().cash.incomes.filter(t=>t.date.startsWith(month)&&t.received&&!salaryLike(t)))+total(tx.filter(t=>t.type==='income'&&!salaryLike(t))),categories=['日常','购物','居住'].map(name=>({name,value:total(counted.filter(t=>t.category===name),t=>expenseSign(t)*t.amount)}));
 return {month,current,past,received,expected,salaryTotal,spent,cashSpent:spent,paid,unpaid,futureFixed,futureDaily,daily,left,now,forecast,retention,otherIncome,categories,count:counted.length,sample:variable.length,allocated:total(state().goals.flatMap(g=>g.entries).filter(e=>e.date.startsWith(month))),historyAssets:v3().cash.opening||0};
}
cashSummary=salarySummary;M.available=()=>salarySummary().forecast;
const originalReset04=M.reset;M.reset=()=>{originalReset04();state().v4={density:'comfortable',wallpaper:null};salaryMonth=M.month();return state();};
const originalEntity04=newEntity;newEntity=function(kind,id){const r=originalEntity04(kind,id);if(kind==='transaction')r.draft.funding??='salary';return r;};
schema.transaction.funding={label:'从哪里支出',choices:[['salary','本月工资'],['assets','历史存款等其他资金']]};
function itemBadge(item,cls=''){const tint=['blue','lilac','coral','mint','ink'].includes(item.badgeTint)?item.badgeTint:'blue';let content;if(item.badgeType==='image'&&/^data:image\/(png|jpeg|webp);base64,/.test(item.badge||''))content=`<img src="${h(item.badge)}" alt="自定义图标">`;else if(item.badgeType==='emoji')content=`<span>${h(String(item.badge||'✨').slice(0,16))}</span>`;else content=icon(item.badgeType==='symbol'?item.badge||item.icon:item.icon||'bag');return `<span class="item-badge tint-${tint} ${cls}">${content}</span>`;}
function periodButton(){return action('v4-period',`${Number(salaryMonth.slice(5))}月工资 ${icon('down')}`,'period-button');}
header=function(title,tools=''){return `<header class="page-header"><div class="eyeline"><span>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><span class="demo-dot">体验版 04</span></div><div class="title-line"><h1>${title}</h1><div class="toolbar">${tools}</div></div></header>`;};
function salaryBar(c){const base=Math.max(1,c.salaryTotal,c.spent+c.paid+c.unpaid+c.futureFixed+c.futureDaily),parts=[{label:'已花',n:Math.max(0,c.spent+c.paid),cls:'spent'},{label:'待付',n:c.unpaid+c.futureFixed,cls:'reserved'},{label:'后续日常',n:c.futureDaily,cls:'projected'},{label:'预计留住',n:Math.max(0,c.forecast),cls:'retained'}];return `<div class="salary-bar" aria-label="工资去向">${parts.map(p=>`<span class="${p.cls}" style="flex:${Math.max(.01,p.n/base)}" title="${p.label} ${yuan(p.n)}"></span>`).join('')}</div><div class="salary-legend">${parts.map(p=>`<span><i class="${p.cls}"></i>${p.label}</span>`).join('')}</div>`;}
home=function(){const c=salarySummary(salaryMonth),g=state().goals[0];return header('这月工资',action('v3-themes','<span class="theme-dot"></span>','round-button','aria-label="外观皮肤"'))+
`<section class="salary-hero"><div class="salary-hero-top">${periodButton()}<span class="scope-label">${icon('wallet')}只算工资</span></div><p class="salary-kicker">${c.past?'月末留下了':'月底预计留下'}</p><div class="salary-number ${c.forecast<0?'negative':''}"><span>${c.forecast<0?'−¥':'¥'}</span>${money(Math.abs(c.forecast),0)}</div><div class="salary-retention">${c.salaryTotal?`这月工资的 <strong>${money(c.retention,1)}%</strong>`:'先确认这月到手工资'}${action('v3-forecast','查看怎么算 '+icon('info'),'link')}</div>${salaryBar(c)}<div class="salary-pair"><div><span>当月工资到账</span><strong>${yuan(c.received)}</strong></div><div><span>目前还留下</span><strong>${yuan(c.now)}</strong></div></div></section>
<p class="scope-note">${icon('shield')}历史存款、其他收入与余额校准都不加进来。</p>
<div class="salary-actions">${action('v3-income',icon('wallet')+'工资到账','primary')}${action('calculator',icon('clock')+'买它花多少时间','secondary')}</div>
${section('接下来要付','v3-repayments','看应还')}${group(`<div class="plain-row"><span>本月分期与应还</span><strong>${yuan(c.unpaid)}</strong></div><div class="plain-row"><span>月底前日常支出 · 估计</span><strong>${yuan(c.futureDaily)}</strong></div>`)}
${action('v4-flow',`<span class="capture-mark">${icon('book')}</span><span><strong>这份工资，花到哪里了？</strong><small>消费、还款与留存，一起看清楚</small></span>${chevron()}`,'capture-banner')}
${g?section('独立的存钱目标','go-goals','看全部')+goalCard(g):''}${note('按已收录数据估算。默认本月现金支出从这月工资扣除；某笔用其他资金，可在明细里改归属。')}`;};
function flowRecords(c){const tx=M.monthlyTx(c.month),income=v3().cash.incomes.filter(i=>i.received&&i.date.startsWith(c.month)).map(i=>({...i,type:'income',account:salaryLike(i)?'工资到账':'其他收入',_cashIncome:true}));return [...tx,...income].sort((a,b)=>b.date.localeCompare(a.date));}
ledger=function(){const c=salarySummary(salaryMonth),records=flowRecords(c);return header('工资流向',iconButton('v3-collection','upload','补齐账单'))+`<div class="flow-period">${periodButton()}<span>不含历史资产</span></div><div class="flow-view-switch"><button data-flow="summary" class="${flowView==='summary'?'active':''}">一眼看清</button><button data-flow="records" class="${flowView==='records'?'active':''}">查一笔明细</button></div>`+(flowView==='summary'?`
<div class="flow-wallet"><div class="flow-income"><span>${icon('wallet')}这月工资</span><strong>${yuan(c.received)}</strong></div><div class="flow-connector"></div><div class="flow-split"><div><span>已花出去</span><strong>${yuan(c.spent+c.paid)}</strong></div><div><span>仍然留下</span><strong>${yuan(c.now)}</strong></div></div></div>
${section('已经花出去的')}${group(c.categories.map((x,i)=>`<button class="flow-category" data-action="v4-filter-records" data-category="${x.name}"><span class="category-symbol category-${i}">${icon(['coffee','bag','house'][i])}</span><span class="flex-copy"><strong>${x.name}</strong><span class="category-track"><i style="width:${Math.max(0,Math.min(100,x.value/Math.max(1,c.received)*100))}%"></i></span></span><strong>${yuan(x.value)}</strong>${chevron()}</button>`).join('')+`<div class="flow-category"><span class="category-symbol category-3">${icon('plan')}</span><span class="flex-copy"><strong>已经还掉的分期</strong><small>现金只在还款时扣一次</small></span><strong>${yuan(c.paid)}</strong></div>`)}
${section('工资留存与存钱记录')}${group(`<div class="plain-row"><span>当前工资留存</span><strong>${yuan(c.now)}</strong></div><div class="plain-row"><span>目标本月${c.allocated>=0?'净存入':'净取出'} · 单独记录</span><strong>${yuan(Math.abs(c.allocated))}</strong></div><div class="plain-row"><span>${c.past?'该月工资结余':'扣除后续支出，预计月底留存'}</span><strong>${yuan(c.forecast)}</strong></div>`)}${note('目标余额可能含历史存款，独立记录；自己转存不视为消费，不从工资结余再扣一次。')}
${section('需要时再处理')}${group(row('补齐一份账单','一次批量收录','v3-collection','','upload')+row('工资外收入与历史资金',`${yuan(c.otherIncome)} 其他收入`,'v4-assets','','wallet')+row('补一笔遗漏','可选','new-transaction','','edit'))}${note(`当前收录 ${records.length} 笔。网页尚未自动获取账单，缺漏会影响结果。`)}`:
`<div class="search-box">${icon('search')}<input type="search" id="ledger-search" value="${h(ledgerSearch)}" placeholder="搜索名称，不用翻长列表" aria-label="搜索收支">${action('ledger-account',h(ledgerAccount)+icon('down'),'account-filter')}</div><div class="chips">${['全部','日常','购物','居住','收入'].map(x=>pill(x,ledgerFilter===x,`data-filter="${x}"`)).join('')}</div>${group(records.filter(t=>(!ledgerSearch||t.name.includes(ledgerSearch))&&(ledgerAccount==='全部'||t.account===ledgerAccount)&&(ledgerFilter==='全部'||ledgerFilter==='收入'&&t.type==='income'||t.category===ledgerFilter)).map(transaction).join(''))}${action('new-transaction','补一笔遗漏','text-button full')}`);};
forecastView=function(){const c=salarySummary(salaryMonth);return sheetChrome('只看这月工资',`<div class="detail-hero"><span>${c.past?'已记录的月末工资结余':'预计月底工资留存'}</span><strong>${yuan(c.forecast)}</strong></div>${group([['当月已到账工资',c.received],['本月尚待到账工资',c.expected],['已支付的现金消费（退款已抵扣）',-c.spent],['实际已还分期',-c.paid],['本月待还与固定支出',-c.unpaid-c.futureFixed],[`剩余 ${c.left} 天日常支出估计`,-c.futureDaily]].map(([label,n])=>`<div class="plain-row"><span>${label}</span><strong>${n<0?'−':''}${yuan(Math.abs(n))}</strong></div>`).join(''))}${note('历史存款、资产总额、其他收入、旧余额校准，都不参与。存入自己的目标不算消费。默认现金支出归本月工资，可在某笔明细中改成“其他资金”。')}${note(`这是按月份归因的收入结余，不追踪银行卡中每一元的来源。未来日常支出按本月 ${c.sample} 笔非固定现金记录估计；漏记仍会影响结果。`)}${action('v3-fixed','调整确定要付的固定账单','secondary full')}`);};
const openBase04=open;open=function(r,push=true){$('#toast').classList.remove('visible');openBase04(r,push);};
const incomeView04=incomeView;incomeView=function(r){return incomeView04(r).replace(/<label class="compact-input">本月开始时可用的钱（选填）[\s\S]*?<\/label>/,'').replace('月底余额预测','工资留存').replace('月底预测','工资留存');};
function assetsView04(){const c=salarySummary(salaryMonth);return sheetChrome('工资以外，分开看',`${group(`<div class="plain-row"><span>本月其他收入</span><strong>${yuan(c.otherIncome)}</strong></div><div class="plain-row"><span>历史资金记录</span><strong>${yuan(v3().cash.opening||0)}</strong></div>`)}<p class="sheet-subtitle">这些钱不会加到首页的“本月工资留存”。这里也不是完整资产负债表。</p><div class="compact-input"><label for="historical-assets">历史资金金额（可选）</label><input id="historical-assets" type="number" inputmode="decimal" min="0" max="999999999" value="${v3().cash.opening||0}"></div>${action('v4-save-assets','保存历史资金','primary full')}${action('v3-other-income','记一笔工资外收入','text-button full')}`);}
function timeEquivalent(amount){const w=state().work,dayHours=w.hours+(w.basis==='real'?w.commuteMinutes/60:0),hourly=M.rate(),hours=hourly>0?amount/hourly:0,days=hours/dayHours,months=days/w.days,roundedMinutes=Math.round(hours*60),dayMinutes=dayHours*60,fullDays=Math.floor(roundedMinutes/dayMinutes),remaining=Math.round(roundedMinutes-fullDays*dayMinutes),wholeHours=Math.floor(remaining/60),minutes=remaining%60;return {hours,days,months,naturalDays:months*30.44,primary:hourly<=0?'当前口径无法折算':fullDays?`${fullDays}个工作日${wholeHours?` ${wholeHours}小时`:''}${minutes?` ${minutes}分钟`:''}`:wholeHours?`${wholeHours}小时${minutes?` ${minutes}分钟`:''}`:`${minutes}分钟`};}
function timeBreakdown(amount){const t=timeEquivalent(amount),w=state().work;return `<div class="time-equivalence"><span>买下它，相当于</span><strong>${t.primary}</strong><div class="time-reference-grid"><div><strong>${money(t.months,2)}</strong><span>个月的工作收入</span></div><div><strong>${money(t.naturalDays,1)}</strong><span>个自然日的收入</span></div><div><strong>${money(t.hours,1)}</strong><span>小时的工作投入</span></div></div><p>按每月${w.days}个工作日、每天${w.hours}小时${w.basis==='real'?'及通勤成本':''}折算；自然日按平均每月30.44天，含休息日。</p></div>`;}
function quoteFinance(d){const n=d.terms||1;if(n===1)return {ready:true,total:d.price,cost:0,rows:M.finance(d.price,1,'zero',0,0).rows};if(d.entry==='rate'){const f=M.finance(d.price,n,d.mode,d.rate,d.upfront);return {...f,ready:true};}const totalPrice=d.entry==='payment'?M.round((d.quotedPayment||0)*n+(d.quotedUpfront||0)):Number(d.quotedTotal||0);if(!(totalPrice>0))return {ready:false,total:0,cost:0,rows:[]};const rows=M.finance(totalPrice,n,'zero',0,0).rows;return {ready:true,total:totalPrice,cost:M.round(totalPrice-d.price),rows};}
const calcDraft04=calculatorDraft;calculatorDraft=function(price=2999,name='降噪耳机'){const r=calcDraft04(price,name);Object.assign(r.draft,{entry:'total',quotedTotal:null,quotedPayment:null,quotedUpfront:0});return r;};
function calculatorResults04(d){const f=quoteFinance(d);if(!f.ready)return `<div class="quote-empty">${icon('info')}填“分期总还款”或“每期含息金额”，就能直接算多付多少钱。<small>不会再把已经包含的利息加一次。</small></div>${timeBreakdown(d.price)}`;const current=salarySummary(),thisMonth=d.terms===1?f.total:f.rows[0].total,remaining=M.round(current.forecast-thisMonth);return `${d.terms>1?`<div class="quote-difference"><div><span>原价 / 融资本金</span><strong>${yuan(d.price)}</strong></div><div><span>分期合计需还</span><strong>${yuan(f.total)}</strong></div><div class="quote-cost"><span>${f.cost>=0?'一共多付的息费':'比原价少付'}</span><strong>${yuan(Math.abs(f.cost))}</strong></div></div>${f.cost<0?note('总还款低于原价，可能存在优惠或未计入首付；保存前请核对。'):note('差额是利息与其他费用合计，单凭总价不能拆出各项。已包含的费用不会重复计算。')}`:''}${timeBreakdown(f.total)}${group(`<div class="plain-row"><span>${d.terms>1?'首期应还（费用已含）':'这次支付'}</span><strong>${yuan(thisMonth)}</strong></div><div class="plain-row"><span>预计月底工资留存将变为</span><strong class="${remaining<0?'negative':''}">${yuan(remaining)}</strong></div>`)}${d.terms>1?`<details class="optional-settings"><summary>展开 ${d.terms} 期应还 ${icon('down')}</summary>${group(f.rows.map((r,i)=>`<div class="plain-row"><span>第 ${i+1} 期</span><strong>${yuan(r.total)}</strong></div>`).join(''))}</details>`:''}`;}
calculatorView=function(r){const d=r.draft;d.entry??='total';return sheetChrome('买它，花多少时间',`<input id="quick-product" class="inline-name" value="${h(d.name)}" placeholder="想买什么（可不填）" aria-label="商品名称"><div class="price-entry"><label for="calc-price">${d.terms>1?'原价 / 实际融资本金':'商品价格'}</label><div><span>¥</span><input id="calc-price" type="number" inputmode="decimal" min=".01" max="9999999" step=".01" value="${d.price}" aria-label="商品原价"></div></div><div class="term-options">${[1,3,6,12].map(n=>pill(n===1?'一次付清':`${n}期`,d.terms===n,`data-terms="${n}"`)).join('')}</div>${d.terms>1?`<div class="quote-mode"><button data-quote-mode="total" class="${d.entry==='total'?'active':''}">知道总还款</button><button data-quote-mode="payment" class="${d.entry==='payment'?'active':''}">知道每期金额</button><button data-quote-mode="rate" class="${d.entry==='rate'?'active':''}">知道费率</button></div>${d.entry==='total'?`<div class="quoted-amount"><label for="quoted-total">分期后，总共还多少钱（已含全部息费）</label><div><span>¥</span><input id="quoted-total" type="number" inputmode="decimal" min=".01" max="99999999" step=".01" value="${d.quotedTotal??''}" placeholder="例如 6240"></div></div>`:d.entry==='payment'?`<div class="quoted-amount"><label for="quoted-payment">每一期应还（已经包含利息）</label><div><span>¥</span><input id="quoted-payment" type="number" inputmode="decimal" min=".01" max="9999999" step=".01" value="${d.quotedPayment??''}" placeholder="例如 520"></div></div>`:`<div class="inline-fees"><label>费用方式<select id="quick-fee-mode"><option value="zero" ${d.mode==='zero'?'selected':''}>免息</option><option value="flat" ${d.mode==='flat'?'selected':''}>每期固定费率</option><option value="apr" ${d.mode==='apr'?'selected':''}>年利率 · 等额本息</option></select></label>${d.mode!=='zero'?`<label>${d.mode==='apr'?'年利率':'每期费率'}<span><input id="quick-fee-rate" type="number" inputmode="decimal" min="0" max="100" step=".01" value="${d.rate}">%</span></label>`:''}</div>`}<details class="optional-settings"><summary>其他期数与还款日 ${icon('down')}</summary><div class="inline-fees"><label>期数<input id="quick-fee-terms" type="number" min="2" max="60" value="${d.terms}"></label><label>还款日<input id="quick-fee-day" type="number" min="1" max="31" value="${d.day}"></label>${d.entry==='rate'?`<label>首期手续费<input id="quick-fee-upfront" type="number" inputmode="decimal" min="0" max="999999" value="${d.upfront}"></label>`:''}</div></details>`:''}<div id="calc-results">${calculatorResults04(d)}</div>${action('v4-save-calculation',d.terms>1?'按这个总金额，加入应还':'收藏这个心愿','primary full')}${d.terms>1?action('v4-save-calc-wish','先收藏，不加入应还','text-button full'):''}${note('总价含全部费用时直接相减；若还有额外服务费，应先计入总还款。原价若含首付，应填写扣除首付后的实际融资本金。')}`);};
// Keep salary transfers out of consumption.
const goalView04=goalView;goalView=function(r){return goalView04(r).replace('本月存入会减少首页可安排金额；取出会释放。已有历史存款不再重复扣除。','在自己名下存入或取出不算消费，工资留存保持不变。这里只记录目标进度。');};
const moveView04=moveView;moveView=function(r){return moveView04(r).replace('data-action="save-move"','data-action="v4-save-move"');};
const symbolOptions=['headphone','plane','book','bag','mountain','house','coffee','wallet','clock','spark','food','user'];
const emojiOptions=['🎧','📱','💻','📷','🚗','🏠','🏝️','🎮','📚','✨','🎸','🧳','🚲','🐱','🎁','🌙'];
function badgePicker04(d){return `<details class="badge-picker"><summary>${itemBadge(d)}<span>自定义图标<small>符号、Emoji 或自己的图片</small></span>${icon('down')}</summary><div class="badge-symbols">${symbolOptions.map(name=>`<button data-badge-symbol="${name}" aria-label="选择${name}图标">${icon(name)}</button>`).join('')}</div><div class="badge-emojis">${emojiOptions.map(emoji=>`<button data-badge-emoji="${emoji}" aria-label="选择${emoji}">${emoji}</button>`).join('')}</div><div class="custom-badge-input"><input id="badge-text" placeholder="也可以输入自己的 Emoji / 简短文字" maxlength="16" aria-label="自定义图标文字">${action('v4-badge-text','用这个','link')}</div><div class="badge-tints">${['blue','lilac','coral','mint','ink'].map(t=>`<button data-badge-tint="${t}" class="tint-${t}" aria-label="图标底色${t}"></button>`).join('')}${action('v4-upload-badge','使用自己的图片','link')}</div></details>`;}
quickWishView=function(r){const d=r.draft;return sheetChrome(r.kind==='goal'?'存钱目标':'收藏心愿',`<div class="quick-cover">${coverImg(d)}${itemBadge(d,'quick-badge')}</div>${coverPicker(d)}<input class="inline-name" id="quick-wish-name" value="${h(d.name)}" maxlength="40" placeholder="给它起个名字" aria-label="名称"><div class="price-entry"><label for="quick-wish-price">${r.kind==='goal'?'想存到多少':'大概价格'}</label><div><span>¥</span><input id="quick-wish-price" type="number" inputmode="decimal" min=".01" max="9999999" value="${r.kind==='goal'?d.target:d.price}" aria-label="目标金额或价格"></div></div>${badgePicker04(d)}${note('封面和图标分别选择。开始存钱不要求月计划，之后存一笔就有进度。')}`,'v3-save-wish');};
const wishView04=wishView;wishView=function(r){const w=state().wishes.find(x=>x.id===r.id);return wishView04(r).replace(`<span>${icon(w?.icon||'bag')}</span>`,itemBadge(w||{},'wish-detail-badge'));};
goalCard=function(g){const b=M.balance(g),pct=Math.min(100,Math.max(0,b/g.target*100));return action('goal',`<div class="saving-cover">${coverImg(g)}<span class="saving-tag">已经在攒</span>${itemBadge(g,'saving-badge')}<strong>${h(g.name)}</strong></div><div class="saving-body"><div><span>已存 ${yuan(b)} <small>/ ${yuan(g.target)}</small></span><strong>${money(pct)}<small>%</small></strong></div><div class="progress"><i style="width:${pct}%"></i></div><p>还差 ${yuan(Math.max(0,g.target-b))}<span>存一笔 ${chevron()}</span></p></div>`,'card visual-goal',`data-id="${h(g.id)}"`);};
plan=function(){const goals=planTab==='goals';return header('期待',iconButton(goals?'v3-new-goal':'v3-new-wish','plus',goals?'新建目标':'收藏心愿'))+`<div class="expect-tabs">${[['wishes','先收藏',state().wishes.length],['goals','已经在攒',state().goals.length]].map(([key,label,count])=>`<button data-plan="${key}" class="${planTab===key?'active':''}">${label}<span>${count}</span></button>`).join('')}</div>`+(goals?state().goals.map(goalCard).join('')||empty('选一个期待，开始攒','不要求月计划，存入一点就留下进度。','v3-new-goal','开始一个目标'):`<div class="wish-grid">${state().wishes.map(w=>action('wish',`<div>${coverImg(w)}${itemBadge(w,'wish-photo-badge')}</div><section><h3>${h(w.name)}</h3><strong>${yuan(w.price)}</strong><p>≈ ${money(timeEquivalent(w.price).days,1)} 个工作日</p></section>`,'photo-wish',`data-id="${h(w.id)}"`)).join('')}</div>${action('v3-new-wish','＋ 收藏一个心愿','add-line')}`);};
const packDescriptions={frost:{name:'清透',caption:'浮层玻璃 · 系统字形 · 圆润分组'},cream:{name:'纸页',caption:'纸张肌理 · 衬线数字 · 细线列表'},forest:{name:'留白',caption:'开放排版 · 轻量卡片 · 宽松间距'},night:{name:'卡包',caption:'金属渐变 · 深色卡面 · 浮动导航'}};
for(const t of themes)Object.assign(t,packDescriptions[t.id]);
function themesView04(){return sheetChrome('选择一种界面质感',`<div class="skin-grid">${themes.map(t=>`<button data-skin="${t.id}" class="skin-card skin-pack-${t.id} ${v3().theme===t.id?'selected':''}"><div class="pack-preview"><span>这月工资</span><strong>¥6,720</strong><div class="pack-line"></div><div class="pack-pair"><i></i><i></i></div><div class="pack-nav"><b></b><b></b><b></b></div></div><div><strong>${t.name}</strong>${v3().theme===t.id?icon('check'):''}</div><small>${t.caption}</small></button>`).join('')}</div>${section('界面密度')}<div class="density-control">${[['comfortable','舒展'],['compact','紧凑']].map(([key,label])=>`<button data-density="${key}" class="${v4().density===key?'active':''}">${label}</button>`).join('')}</div>${section('背景也可以是自己的')}<div class="wallpaper-options">${Object.entries(covers).slice(0,3).map(([key,c])=>`<button data-wallpaper="${key}" aria-label="${c.name}背景"><img src="${c.src}" alt="${c.name}"></button>`).join('')}${action('v4-upload-wallpaper',icon('plus'),'wallpaper-upload','aria-label="上传自己的背景"')}</div>${v4().wallpaper?action('v4-clear-wallpaper','恢复主题默认背景','text-button full'):note('可以上传本机照片。文字区域保留清晰底色，避免影响金额阅读。')}${note('布局、材质、圆角、数字字形和导航风格会一起变化。点选立即应用，不需要另存。')}`);}
themesView=themesView04;
const profileView04=profile;profile=function(){return profileView04().replace('体验版 03','体验版 04').replace('主题、配色与深色外观','材质、排版、图标与背景').replace('工资到账记录</span>','工资到账记录</span>').replace('时薪 '+yuan(M.rate()),'时薪 '+yuan(M.rate()));};
// Short, interruptible transitions. Nav selection persists while content crossfades.
let navAnimations=[],navSnapshot=null,lastPlan04=planTab;
const renderBase04=render;render=function(keep=true){renderBase04(keep);document.body.dataset.density=v4().density;$('#app-shell').dataset.density=v4().density;const wall=v4().wallpaper,src=covers[wall]?.src||(/^data:image\/(png|jpeg|webp);base64,/.test(wall||'')?wall:'');$('#app-shell').style.setProperty('--user-wallpaper',src?`url("${src}")`:'none');$('#app-shell').classList.toggle('has-wallpaper',!!src);$('#tab-bar').style.setProperty('--tab-index',navs.findIndex(n=>n[0]===tab));if(lastPlan04!==planTab&&tab==='plan'&&!matchMedia('(prefers-reduced-motion: reduce)').matches)app.animate([{opacity:.5,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:170,easing:'ease-out'});lastPlan04=planTab;};
const scrollMemory04={};navigate=function(next){if(!navs.some(n=>n[0]===next))return;const previous=tab;if(next===previous&&!route){app.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}navAnimations.forEach(a=>a.cancel());navSnapshot?.remove();scrollMemory04[previous]=app.scrollTop;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,clone=!reduced&&previous!==next?app.cloneNode(true):null;close();tab=next;render(false);app.scrollTop=scrollMemory04[next]||0;if(clone){clone.removeAttribute('id');clone.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));clone.classList.add('page-snapshot');clone.setAttribute('aria-hidden','true');clone.inert=true;$('#app-shell').insertBefore(clone,$('#tab-bar'));clone.scrollTop=scrollMemory04[previous]||0;navSnapshot=clone;const direction=navs.findIndex(n=>n[0]===next)>navs.findIndex(n=>n[0]===previous)?1:-1;const outgoing=clone.animate([{opacity:1,transform:'translateX(0)'},{opacity:0,transform:`translateX(${-direction*12}px)`}],{duration:190,easing:'ease-out',fill:'forwards'}),incoming=app.animate([{opacity:.2,transform:`translateX(${direction*15}px)`},{opacity:1,transform:'translateX(0)'}],{duration:260,easing:'cubic-bezier(.16,1,.3,1)'});navAnimations=[outgoing,incoming];outgoing.finished.then(()=>clone.remove()).catch(()=>clone.remove());}};
function customControls04(){sheet.querySelectorAll('select:not([data-customized])').forEach(select=>{select.dataset.customized='true';const anchor=document.createElement('div');anchor.className='apple-select';const button=document.createElement('button');button.type='button';button.className='apple-select-button';button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label',select.closest('label')?.childNodes[0]?.textContent||'选择');button.innerHTML=`<span>${h(select.selectedOptions[0]?.textContent||'选择')}</span>${icon('down')}`;select.before(anchor);anchor.append(button,select);select.hidden=true;select.tabIndex=-1;let menu;button.addEventListener('click',()=>{if(menu&&!menu.isConnected)menu=null;if(menu){menu.remove();menu=null;button.setAttribute('aria-expanded','false');return;}menu=document.createElement('div');menu.className='apple-choice-menu';menu.setAttribute('role','listbox');[...select.options].forEach(option=>{const item=document.createElement('button');item.type='button';item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.value===select.value));item.innerHTML=`<span>${h(option.textContent)}</span>${option.value===select.value?icon('check'):''}`;item.addEventListener('click',()=>{select.value=option.value;button.innerHTML=`<span>${h(option.textContent)}</span>${icon('down')}`;menu?.remove();menu=null;button.setAttribute('aria-expanded','false');select.dispatchEvent(new Event('change',{bubbles:true}));});menu.append(item);});anchor.append(menu);button.setAttribute('aria-expanded','true');menu.querySelector('button')?.focus({preventScroll:true});});anchor.addEventListener('focusout',()=>setTimeout(()=>{if(menu&&!anchor.contains(document.activeElement)){menu.remove();menu=null;button.setAttribute('aria-expanded','false');}},80));});}
const renderSheetBase04=renderSheet;renderSheet=function(){const views={themes:themesView04,assets04:assetsView04,period04:()=>sheetChrome('选择月份',group([...new Set([M.month(),...v3().cash.incomes.map(i=>i.date.slice(0,7)),...state().transactions.map(t=>t.date.slice(0,7)),M.shiftMonth(M.month(),-1)])].sort().reverse().slice(0,12).map(m=>`<button class="choice-row" data-salary-month="${m}"><span>${m.replace('-','年')}月</span>${m===salaryMonth?icon('check'):''}</button>`).join('')))};if(views[route.type]){sheet.innerHTML=views[route.type](route);sheet.hidden=false;backdrop.hidden=false;app.inert=true;$('#tab-bar').inert=true;$('#desktop-nav').inert=true;sheet.scrollTop=0;sheet.focus({preventScroll:true});}else renderSheetBase04();customControls04();sheet.setAttribute('aria-label',sheet.querySelector('.sheet-nav>strong')?.textContent||'详情');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)sheet.querySelector('.sheet-body')?.animate([{opacity:.5,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:160,easing:'ease-out'});};
function refreshCalculator04(){if(route?.type==='calculator'&&$('#calc-results'))$('#calc-results').innerHTML=calculatorResults04(route.draft);}
function buildQuotedDebt04(d,f){const id=M.uid(),priceC=Math.round(d.price*100),totalC=Math.round(f.total*100);let accumulated=0,previousPrincipal=0;const schedule=f.rows.map((r,i)=>{const rowC=Math.round(r.total*100);accumulated+=rowC;const cumulativePrincipal=f.cost<0?accumulated:Math.round(accumulated*priceC/totalC),principal=cumulativePrincipal-previousPrincipal;previousPrincipal=cumulativePrincipal;return {id:M.uid(),date:M.dueDate(M.shiftMonth(d.firstMonth||M.month(),i),d.day),paid:false,principal:principal/100,interest:0,fee:(rowC-principal)/100,total:r.total};});return {id,name:d.name,principal:d.price,originalPrice:d.price,statedTotal:f.total,aggregateCost:f.cost,terms:d.terms,firstMonth:d.firstMonth||M.month(),day:d.day,mode:'statement',rate:0,upfront:0,unknownBreakdown:true,quotedCostKnown:true,schedule};}
function chooseLocalImage04(onDone){chooseFile('image/jpeg,image/png,image/webp',async file=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>600*1024)throw new Error('请选择小于600KB的JPG、PNG或WebP图片');const reader=new FileReader();reader.onload=()=>onDone(reader.result);reader.readAsDataURL(file);});}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;try{if(b.dataset.salaryMonth){salaryMonth=b.dataset.salaryMonth;close();render(false);return;}if(b.dataset.flow){flowView=b.dataset.flow;render();return;}if(b.dataset.quoteMode){if(!validateCalculator())return;route.draft.entry=b.dataset.quoteMode;renderSheet();return;}if(b.dataset.badgeSymbol||b.dataset.badgeEmoji||b.dataset.badgeTint){rememberWishDraft();if(b.dataset.badgeSymbol){route.draft.badgeType='symbol';route.draft.badge=b.dataset.badgeSymbol;}if(b.dataset.badgeEmoji){route.draft.badgeType='emoji';route.draft.badge=b.dataset.badgeEmoji;}if(b.dataset.badgeTint)route.draft.badgeTint=b.dataset.badgeTint;renderSheet();sheet.querySelector('.badge-picker').open=true;return;}if(b.dataset.density){v4().density=b.dataset.density;persist();render();renderSheet();return;}if(b.dataset.wallpaper){v4().wallpaper=b.dataset.wallpaper;persist();render();renderSheet();return;}
const a=b.dataset.action;if(a==='v4-period')open({type:'period04'});else if(a==='v4-flow')navigate('ledger');else if(a==='v4-filter-records'){flowView='records';ledgerFilter=b.dataset.category;render();}else if(a==='v4-assets')open({type:'assets04'});else if(a==='v4-save-assets'){v3().cash.opening=numericValue('#historical-assets',0,999999999);persist();close();render();toast('已单独保存，不影响这月工资');}
else if(a==='v4-save-calculation'||a==='v4-save-calc-wish'){if(!validateCalculator())return;const d=route.draft;d.name=$('#quick-product').value.trim()||'一个想买的东西';const f=quoteFinance(d);if(d.terms>1&&a==='v4-save-calculation'){if(!f.ready)throw new Error('填一下总还款或每期金额，就能按实际应还保存');if(d.entry==='rate')state().debts.unshift(M.makeDebt({id:M.uid(),name:d.name,principal:d.price,terms:d.terms,mode:d.mode,rate:d.rate,upfront:d.upfront,day:d.day,firstMonth:d.firstMonth}));else state().debts.unshift(buildQuotedDebt04(d,f));persist();close();render();toast('按已含息费的总金额加入，没有重复加息');}else{state().wishes.unshift({id:M.uid(),name:d.name,price:d.price,icon:'bag',cover:'headphones',note:''});persist();planTab='wishes';navigate('plan');toast('已收藏');}}
else if(a==='v4-save-move'){const g=state().goals.find(x=>x.id===route.id),amount=numericValue('#move-amount',.01,9999999);if(route.withdraw&&amount>M.balance(g))throw new Error('取出金额不能超过已存金额');g.entries.push({id:M.uid(),amount:route.withdraw?-amount:amount,date:M.today(),note:$('#move-note').value.trim()});persist();returnParent();render();toast('存钱进度已更新，工资留存不变');}
else if(a==='v4-badge-text'){const value=$('#badge-text').value.trim();if(!value)throw new Error('输入一个图标文字或Emoji');rememberWishDraft();Object.assign(route.draft,{badgeType:'emoji',badge:value});renderSheet();sheet.querySelector('.badge-picker').open=true;}else if(a==='v4-upload-badge'){rememberWishDraft();chooseLocalImage04(data=>{Object.assign(route.draft,{badgeType:'image',badge:data});renderSheet();sheet.querySelector('.badge-picker').open=true;});}else if(a==='v4-upload-wallpaper')chooseLocalImage04(data=>{v4().wallpaper=data;persist();render();renderSheet();});else if(a==='v4-clear-wallpaper'){v4().wallpaper=null;persist();render();renderSheet();}
}catch(e){toast(e.message||'请检查输入');}});
document.addEventListener('input',e=>{if(route?.type!=='calculator')return;const d=route.draft;if(e.target.id==='quoted-total'){const v=Number(e.target.value);d.quotedTotal=Number.isFinite(v)&&v>=0&&v<=99999999?v:null;}if(e.target.id==='quoted-payment'){const v=Number(e.target.value);d.quotedPayment=Number.isFinite(v)&&v>=0&&v<=9999999?v:null;}if(['calc-price','quoted-total','quoted-payment'].includes(e.target.id))refreshCalculator04();});
navs.splice(0,navs.length,['home','工资','wallet'],['ledger','流向','book'],['plan','期待','mountain'],['profile','设置','user']);
window.__timeworthPreview.salarySummary=salarySummary;window.__timeworthPreview.cashSummary=salarySummary;window.__timeworthPreview.timeEquivalent=timeEquivalent;window.__timeworthPreview.quoteFinance=quoteFinance;window.__timeworthPreview.buildQuotedDebt=buildQuotedDebt04;
window.__timeworthPreview.navigate=navigate;window.__timeworthPreview.reset=()=>{M.reset();salaryMonth=M.month();planTab='wishes';navigate('home');render(false);};
render(false);
const debtView04=debtView;debtView=function(r){const d=state().debts.find(d=>d.id===r.id),html=debtView04(r);if(!d?.quotedCostKnown)return html;return html.replace('</small></div>',`</small></div><div class="quote-difference"><div><span>原价 / 对应本金</span><strong>${yuan(d.originalPrice)}</strong></div><div><span>这份分期总还款</span><strong>${yuan(d.statedTotal)}</strong></div><div class="quote-cost"><span>${d.aggregateCost>=0?'多付的总息费':'比原价少付'}</span><strong>${yuan(Math.abs(d.aggregateCost))}</strong></div></div>`);};
const parseCommitment04=parseCommitment;parseCommitment=function(input){const d=parseCommitment04(input);if(!d)return d;const original=input.match(/(?:原价|本金|现金价)\s*[¥￥]?\s*(\d+(?:\.\d{1,2})?)/);if(original){d.originalPrice=Number(original[1]);d.name=d.name.replace(/\s*(?:原价|本金|现金价)[\s\S]*$/,'')||'一笔分期';}return d;};
const commitmentPreview04=commitmentPreview;commitmentPreview=function(text){const d=parseCommitment(text),html=commitmentPreview04(text);return d?.originalPrice?html+note(`已知原价 ${yuan(d.originalPrice)}，分期后合计 ${yuan(d.amount*d.terms)}，${d.amount*d.terms>=d.originalPrice?'多付总息费':'比原价少付'} ${yuan(Math.abs(d.amount*d.terms-d.originalPrice))}。`):html;};
const saveCommitment04=saveCommitment;saveCommitment=function(){const parsed=parseCommitment($('#commitment-text').value),oldId=route.id;saveCommitment04();if(parsed?.originalPrice){const d=oldId?state().debts.find(d=>d.id===oldId):state().debts[0];Object.assign(d,{quotedCostKnown:true,originalPrice:parsed.originalPrice,statedTotal:M.round(parsed.amount*parsed.terms),aggregateCost:M.round(parsed.amount*parsed.terms-parsed.originalPrice)});persist();}};
document.addEventListener('pointerdown',event=>{document.querySelectorAll('.apple-choice-menu').forEach(menu=>{const anchor=menu.parentElement;if(!anchor.contains(event.target)){menu.remove();anchor.querySelector('button')?.setAttribute('aria-expanded','false');}});},true);
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;const menus=[...document.querySelectorAll('.apple-choice-menu')];if(!menus.length)return;event.preventDefault();event.stopImmediatePropagation();menus.forEach(menu=>{const button=menu.parentElement.querySelector('button');menu.remove();button?.setAttribute('aria-expanded','false');button?.focus({preventScroll:true});});},true);
const parseMessage04=parseMessage;parseMessage=function(text,source='其他账户'){const t=parseMessage04(text,source);if(t?.type==='income'){const payroll=/工资|薪资|薪酬|年终奖|绩效奖金/.test(text);t.salary=payroll;t.name=payroll?'工资到账':'其他收入到账';}return t;};
window.__timeworthPreview.parseMessage=parseMessage;

const aboutView04=aboutView;aboutView=function(){return aboutView04().replaceAll('体验版 03','体验版 04').replace('工资到账、应还、收录来源和想存的钱，共同形成可解释的月底估算。','只看当月工资留下多少；历史存款和其他收入分开看，转存自己的目标不算消费。').replace('工资到账、余额校准、图片心愿、主题皮肤及备份。','工资结余、分期总息费反推、工作天数换算、自定义图标、材质主题及备份。').replace('<a class="list-row" href="https://docs.sheetjs.com', '<a class="list-row" href="https://developer.apple.com/design/human-interface-guidelines/motion" target="_blank" rel="noopener"><span class="row-label">Apple · 动效与连续体验</span>'+chevron()+'</a><a class="list-row" href="https://developer.apple.com/design/human-interface-guidelines/pickers" target="_blank" rel="noopener"><span class="row-label">Apple · 当前场景中的选择</span>'+chevron()+'</a><a class="list-row" href="https://docs.sheetjs.com');};
